// ===========================================================================
// Фикстура §6.2: актёр стоит краем коллайдера на платформе.
//
// Тело 26x30 стоит так, что 25 % ширины (6.5 px) свисает за правую кромку
// платформы (кромка x = 600, центр тела x = 593.5). Ничего не двигается и не
// нажимается: тест 120 кадров подряд читает позицию, onFloor() и on_ground и
// ищет дрожание, проваливание и чередование опоры.
// ===========================================================================

$.ready(() => {
    $.world.gravity(0, 1800).color('#101820')
        .bounds(-200, -200, 1600, 1200, { solid: false });

    // Платформа: x 400..600, верх y = 384 (центр 400, высота 32).
    $('<wall>', { id: 'ledge' }).at(500, 400).size(200, 32).appendTo($.world);

    // Игрок шириной 26: правый край тела на x = 606.5, то есть 6.5 px (25 %)
    // висят в воздухе. Центр (593.5) остаётся над платформой — именно этот
    // случай ломается, если опора ищется одним лучом из центра.
    $('<player>', { id: 'edge' }).at(593.5, 340).size(26, 30)
        .health(100).controls('both')
        .collision(26, 30).appendTo($.world);
});
